@Entity
@Inheritance(strategy = InheritanceType.SINGLE_TABLE)
@DiscriminatorColumn(name = "payment_type")
abstract class Payment {
    @Id @GeneratedValue
    private Long id;
    private double amount;
}

@Entity
@DiscriminatorValue("CARD")
class CardPayment extends Payment {
    private String cardNumber;
}

@Entity
@Inheritance(strategy = InheritanceType.JOINED)
abstract class PaymentJoined {
    @Id @GeneratedValue
    private Long id;
    private double amount;
}

@Entity
class CardPaymentJoined extends PaymentJoined {
    private String cardNumber; // tabela card_payment_joined: id (FK do payment_joined), card_number
}

// BLAD: SINGLE_TABLE dla podklas o bardzo roznych, licznych polach
@Entity
@Inheritance(strategy = InheritanceType.SINGLE_TABLE)
abstract class Payment {
    @Id @GeneratedValue Long id;
    double amount;
}

@Entity class CardPayment extends Payment { String cardNumber; String cvv; String expiryDate; }
@Entity class TransferPayment extends Payment { String iban; String bankName; String swift; }
@Entity class CryptoPayment extends Payment { String walletAddress; String blockchain; String txHash; }
// tabela payment: 2 wspolne + 9 specyficznych kolumn, kazdy wiersz ma 6 z nich jako NULL

// POPRAWNIE: JOINED dla podklas o duzej roznorodnosci pol - brak pustych kolumn
@Entity
@Inheritance(strategy = InheritanceType.JOINED)
abstract class Payment {
    @Id @GeneratedValue Long id;
    double amount;
}

@Entity class CardPayment extends Payment { String cardNumber; String cvv; String expiryDate; }
@Entity class TransferPayment extends Payment { String iban; String bankName; String swift; }
